for g in range(3):
    for i in range(3): edges.append((g*3+i,(g+1)*3+i))
adj=[[] for _ in range(V)]
for ei,(u,v) in enumerate(edges):
    adj[u].append((v,ei)); adj[v].append((u,ei))
# edge orbits reps with endpoint orientation
reps=[('end_clique',(0,1)),('mid_clique',(3,4)),('outer_match',(0,3)),('mid_match',(3,6))]

def check_partial(labels):
    diffs={}
    for ei,(u,v) in enumerate(edges):
        if labels[u] is not None and labels[v] is not None:
            d=abs(labels[u]-labels[v])
            if d==0 or d in diffs: return None
            diffs[d]=ei
    return set(diffs)

def search(labels, used_mask, nodes=[0], limit=2000000):
    nodes[0]+=1
    if nodes[0]%100000==0:
        print('nodes',nodes[0],'assigned',sum(x is not None for x in labels),'used diffs',len(check_partial(labels) or []), 'labels', labels, flush=True)
    if nodes[0]>limit: return 'LIMIT'
    diffs=check_partial(labels)
    if diffs is None: return None
    if len(diffs)==m:
        if all(x is not None for x in labels): return labels.copy()
        # all edges assigned implies all vertices? graph connected yes.
    # find highest missing diff
    d=None
    for dd in range(m,0,-1):
        if dd not in diffs:
            d=dd; break
    if d is None:
        return labels.copy()
    # Build candidate moves for d
    cand=[]
    for ei,(u,v) in enumerate(edges):
        lu,lv=labels[u],labels[v]
        if lu is not None and lv is not None:
            continue
        if lu is not None or lv is not None:
            if lu is None:
                known_v=v; unk=u; a=lv
            else:
                known_v=u; unk=v; a=lu
            for b in (a-d,a+d):
                if 0<=b<=m and not (used_mask>>b)&1:
                    cand.append((1, ei, [(unk,b)]))
        else:
            # both unassigned; pairs l,l+d
            for a in range(0,m-d+1):
                b=a+d
                if ((used_mask>>a)&1) or ((used_mask>>b)&1): continue
                cand.append((2, ei, [(u,a),(v,b)]))
                cand.append((2, ei, [(u,b),(v,a)]))
    # Heuristic sort: one assignment first? High constraint vertices maybe
    def score(move):
        _,ei,assigns=move; u,v=edges[ei]
        # prefer assignments with endpoints having many assigned neighbors? and labels extremes
        sc=len(assigns)*10 - (len(adj[u])+len(adj[v]))
        return sc
    cand.sort(key=score)
    if not cand: return None
    # maybe remove symmetric duplicates for unlabeled edge pairs? no
    for _,ei,assigns in cand:
        # apply and local check
        ok=True; changed=[]; newmask=used_mask
        for var,val in assigns:
            if labels[var] is not None:
                if labels[var]!=val: ok=False; break
            if (newmask>>val)&1: ok=False; break
            labels[var]=val; changed.append(var); newmask |= 1<<val
        if ok:
            # local duplicate check more efficient use full
            res=search(labels,newmask,nodes,limit)
            if res=='LIMIT': return 'LIMIT'
            if res is not None: return res
        for var in reversed(changed): labels[var]=None
    return None

